solution:
function solve(n, edges) {
  const induk = Array.from({ length: n }, (_, i) => i)
  const cari = (x) =>
    induk[x] === x ? x : (induk[x] = cari(induk[x]))

  let total = 0
  const urut = [...edges].sort((p, q) => p[2] - q[2])
  for (const [u, v, w] of urut) {
    const a = cari(u)
    const b = cari(v)
    if (a !== b) {
      induk[a] = b
      total += w
    }
  }
  return total
}
